export const objectives = [
  { id:'bio-cell-types', world:'bio', name:'Cell types and shared structures',
    lesson:'Representative bacterial and eukaryotic cells both have a plasma membrane, cytoplasm, DNA, and ribosomes. Prokaryotic DNA is not enclosed by a nucleus. Eukaryotic cells usually compartmentalize DNA in a nucleus and have membrane-bound organelles. A wall or the ability to photosynthesize alone does not identify a cell as prokaryotic. Some specialized mature eukaryotic cells lose their nucleus.', sourceUrls:[ADA,PROK,EUK], reviewStatus:'internal-review' },
  { id:'bio-nucleus', world:'bio', name:'The nucleus and genetic compartments',
    lesson:'The nucleus encloses most DNA in a typical nucleated eukaryotic cell. Nuclear pores regulate traffic across its envelope. The nucleolus makes much of the ribosomal RNA and assembles early ribosomal subunits; translation itself occurs on ribosomes. Mitochondria, and chloroplasts when present, also contain DNA. Not every mature cell retains a nucleus.', sourceUrls:[ADA,EUK,ENDO,NUCLEAR_IMPORT], reviewStatus:'internal-review' },
  { id:'bio-cargo', world:'bio', name:'Protein destinations and the secretory route',
    lesson:'In the conventional secretory route, a targeting signal directs a growing protein and its ribosome to rough ER. Cargo then travels in vesicles to the Golgi for processing and sorting, and onward to its destination. A soluble cytosolic protein without an ER-targeting signal is generally made on free ribosomes. A vesicle keeps its lumenal cargo separated from cytosol until fusion opens it to a compatible compartment or the outside.', sourceUrls:[ADA,ENDO,EUK], reviewStatus:'internal-review' },
  { id:'bio-recycling', world:'bio', name:'Lysosomes, peroxisomes and recycling',
    lesson:'Lysosomes use enzymes suited to an acidic lumen to break down delivered material. Autophagy can bring cellular material, including damaged organelles, into this degradative route. Peroxisomes carry out oxidative reactions and use catalase to help process hydrogen peroxide. These compartments are not interchangeable. Plant lytic vacuoles can perform related degradative functions.', sourceUrls:[ADA,EUK,ENDO], reviewStatus:'internal-review' },
  { id:'bio-energy-organelles', world:'bio', name:'Mitochondria and chloroplast compartments',
    lesson:'In mitochondria, the inner membrane houses respiratory electron transport and ATP synthase; the matrix is the internal compartment. Chloroplast light reactions occur in thylakoid membranes, while carbon fixation of the Calvin cycle occurs in the stroma. Photosynthetic plant cells can also respire using mitochondria. Nonphotosynthetic plant cells can use sugars made elsewhere. This introduction does not cover complete metabolic pathways.', sourceUrls:[ADA,EUK,RESPIRATION,LIGHT,FIXATION], reviewStatus:'internal-review' },
  { id:'bio-cytoskeleton', world:'bio', name:'Cellular tracks, shape and movement',
    lesson:'Microtubules provide tracks for some motor-driven cargo and form the mitotic spindle. Actin filaments help shape the cell cortex and can work with myosin in movement. Intermediate filaments such as keratin provide mechanical support. ATP-powered motors supply movement along tracks; the tracks do not provide the ATP. Typical motile eukaryotic cilia use microtubules, but not every cilium is motile or has the same arrangement.', sourceUrls:[ADA,CYTO,CILIA], reviewStatus:'internal-review' },
];
const objectiveById = new Map(objectives.map(o=>[o.id,o]));
function q(topic,suffix,pool,family,prompt,choices,answer,hint,explanation,feedback) {
  const objectiveId=`bio-${topic}`;
  return { id:`bio-${topic}-${suffix}`, objectiveId, familyId:`bio-quarter-${family}`, world:'bio', pool,
    prompt,choices,answer,hint,explanation,feedback,sourceUrls:[...objectiveById.get(objectiveId).sourceUrls],
    reviewStatus:'internal-review',actionLabel:pool==='practice'?'Commit prediction':'Commit answer' };
}

